window.AB620_VIDEO = {"P25":{"src":"video/P25.mp4","duration":167.269,"scenes":[{"start":0},{"start":24.087},{"start":48.766},{"start":72.655},{"start":96.03},{"start":118.229},{"start":142.182}],"cues":[[0.8,5.736,"Maya, a sales rep at Contoso, saves a new account in her model-driven app."],[5.816,8.597,"The app does not write to the database by itself."],[8.677,11.544,"It sends a message called Create to Dataverse."],[11.624,15.729,"Dataverse then runs that message through a pipeline of four stages,"],[15.729,18.992,"and your plug-ins join the stages around the save."],[19.072,23.837,"Think of a restaurant: the order is checked, prepared, cooked, and finally plated."],[24.537,27.575,"The first stop is PreValidation, stage ten."],[27.655,32.527,"It usually runs outside the database transaction, and before the security checks."],[32.607,35.452,"Contoso registers a synchronous plug-in here."],[35.532,37.834,"It sees that the tax number is empty,"],[37.834,42.388,"and throws an Invalid Plugin Execution Exception with a clear message."],[42.468,45.271,"Maya reads the message, and nothing was written."],[45.351,48.516,"This is the cheapest place to cancel an operation."],[49.216,51.976,"Next comes PreOperation, stage twenty."],[52.056,56.608,"Now the database transaction is open, but the row is not saved yet."],[56.688,61.048,"Contoso's second plug-in tidies the account name before it is written."],[61.128,65.445,"Because the plug-in changes the values first, there is no extra update."],[65.525,67.091,"Avoid cancelling here."],[67.171,70.191,"A cancel triggers a rollback of the whole transaction,"],[70.191,72.405,"and that costs a lot of performance."],[73.105,75.588,"Stage thirty is the main operation."],[75.668,79.132,"This is where Dataverse itself writes the new account row."],[79.212,84.66,"The stage is for internal use, with one exception: the plug-ins of custom APIs,"],[84.66,88.308,"and custom virtual table data providers, run here."],[88.388,92.94,"Everything before it is called Pre, and everything after it is called Post."],[93.02,95.78,"The words simply mean before or after this write."],[96.48,101.949,"PostOperation, stage forty, runs after the write and still inside the transaction."],[102.029,106.56,"Contoso creates a follow-up task for Maya here, with a synchronous plug-in."],[106.64,110.376,"If that plug-in throws an error, the whole transaction rolls back,"],[110.376,112.557,"and the new account disappears too."],[112.637,115.064,"Also avoid changing the same account here,"],[115.064,117.979,"because that triggers a brand new Update event."],[118.679,120.991,"Not every job must make Maya wait."],[121.071,124.705,"In PostOperation you can register an asynchronous step."],[124.785,128.501,"It goes into a queue and runs after the operation completes,"],[128.501,130.745,"outside the database transaction."],[130.825,135.377,"It never joins that transaction, so if it fails, the account stays saved."],[135.457,138.58,"Only PostOperation allows asynchronous steps."],[138.66,141.932,"Contoso uses one to send the welcome email."],[142.632,144.859,"On the exam, remember four rules."],[144.939,148.47,"To cancel an operation, use a synchronous PreValidation"],[148.47,152.072,"step and throw an Invalid Plugin Execution Exception."],[152.152,155.957,"To change values before they are saved, use PreOperation."],[156.037,159.245,"Asynchronous steps exist only in PostOperation."],[159.325,163.707,"And an exception in any synchronous stage rolls back the whole transaction."],[163.787,166.269,"Never build logic on the Depth property."]],"poster":"video/P25.jpg"}};
